def skill():
    t = Symbol('t')
    F = integrate(3*t**2 - 12*t + 9, t)
    pts = [0, 1, 3, 5]
    return sum(abs(F.subs(t, b) - F.subs(t, a)) for a, b in zip(pts[:-1], pts[1:]))

def standard():
    t = Symbol('t')
    v = 3*t**2 - 12*t + 9
    return integrate(Abs(v), (t, 0, 5))

def unique():
    return [standard()]
